	fx_tenant_api "github.com/Sokol111/ecommerce-tenant-service-api/pkg/fxconfig"
	"go.uber.org/fx"
)

func NewInfrastructureModule() fx.Option {
	return fx.Options(
		NewTenantModule(),
		NewAdaptersModule(),
	)
}

func NewAdaptersModule() fx.Option {
	return fx.Options(
		fx_mongo.NewMongoModule(),
		fx_imgproxy.NewImgProxyModule(),
		fx_s3.NewS3Module(),
		fx_inbound_kafka.NewKafkaModule(),
		fx_outbound_kafka.NewKafkaModule(),
		fx_token.NewTokenModule(),
		fx_connect.NewConnectModule(),
	)
}

func NewTenantModule() fx.Option {
	return fx.Options(
		fx_tenant_api.NewKafkaConsumerModule(),
		fx_tenant_api.NewTenantSlugsProviderModule(),
		fx_tenant_api.NewGrpcClientsModule(),
	)
}

package fxconfig

import (
	"github.com/Sokol111/ecommerce-commons/pkg/kafka/consumer"
	fx_consumer "github.com/Sokol111/ecommerce-commons/pkg/kafka/consumer/fxconfig"
	"github.com/Sokol111/ecommerce-image-service/internal/infrastructure/inbound/kafka"
	"go.uber.org/fx"
	"go.uber.org/zap"
)

func NewKafkaModule() fx.Option {
	return fx.Options(
		fx.Provide(kafka.NewProductHandler),
		fx_consumer.RegisterHandlerAndConsumer("catalog-events", newProductRouter),
	)
}

func newProductRouter(h *kafka.ProductHandler, log *zap.Logger) consumer.Handler {
	r := consumer.NewRouter(log)
	consumer.Register(r, h.HandleProductUpdated)
	consumer.Register(r, h.HandleProductDeleted)
	return r
}

